import React, { useState, useEffect, useRef } from 'react';

// Helper to get order_id or a fallback
const getOrderId = (event) => {
  if (event && (event.order_id !== undefined && event.order_id !== null)) {
    return event.order_id;
  }
  if (event && event.sequence_id !== undefined) {
    return `seq-${event.sequence_id}`;
  }
  return 'N/A';
};

// Helper to group and narrate events into causal blocks
const groupAndNarrateEvents = (trace, maxSeqIdFilter) => {
  if (!trace || trace.length === 0) return [];

  const sortedTrace = [...trace].sort(
    (a, b) => a.sequence_id - b.sequence_id
  );

  const narrativeBlocks = [];
  let currentOrderId = null;
  let currentQueueProgressionEvents = [];
  let currentQueueParentId = null;

  const flushQueueProgression = () => {
    if (currentQueueProgressionEvents.length > 0) {
      const queueAheads = currentQueueProgressionEvents.map(e => {
        if (e.queue_ahead !== undefined && e.queue_ahead !== null) {
          return e.queue_ahead;
        }
        return '?';
      });

      narrativeBlocks.push({
        group: 'Queue Progression',
        id: currentQueueProgressionEvents[0].sequence_id,
        parentId: currentQueueProgressionEvents[0].parent_sequence_id,
        timestamp: currentQueueProgressionEvents[0].timestamp,
        narrative: `Order ${getOrderId(currentQueueProgressionEvents[0])} waiting in queue, position improving due to market activity: ${queueAheads.join(' → ')}`,
        isKeyEvent: queueAheads.includes(0), // KEY EVENT: Queue cleared
        keyEventMarker: queueAheads.includes(0) ? '⚠ Queue cleared' : null,
      });
      currentQueueProgressionEvents = [];
      currentQueueParentId = null;
    }
  };

  const filteredTrace = maxSeqIdFilter !== null
    ? sortedTrace.filter(event => event.sequence_id <= maxSeqIdFilter)
    : sortedTrace;

  let firstExecutionEventAdded = false; // Flag to detect first execution event

  filteredTrace.forEach((event) => {
    const eventOrderId = getOrderId(event);

    if (
        (event.type !== 'QueueProgression' && currentQueueProgressionEvents.length > 0) ||
        (currentOrderId !== null && eventOrderId !== 'N/A' && eventOrderId !== currentOrderId) ||
        (event.type === 'QueueProgression' && currentQueueProgressionEvents.length > 0 &&
         event.parent_sequence_id !== currentQueueProgressionEvents[0].parent_sequence_id)
    ) {
      flushQueueProgression();
    }

    currentOrderId = eventOrderId;

    let isKeyEvent = false;
    let keyEventMarker = null;

    switch (event.type) {
      case 'OrderIntent':
        narrativeBlocks.push({
          group: 'Intent',
          narrative: `Strategy decision: Order ${getOrderId(event)} placed for ${event.quantity} at price ${event.price} (Side: ${event.side}).`,
          id: event.sequence_id,
          parentId: event.parent_sequence_id,
          timestamp: event.timestamp,
          isKeyEvent,
          keyEventMarker,
        });
        break;
      case 'OrderEnteredQueue':
        narrativeBlocks.push({
          group: 'Queue Entry',
          narrative: `Order ${getOrderId(event)} entered the queue at position ${event.queue_ahead}.`,
          id: event.sequence_id,
          parentId: event.parent_sequence_id,
          timestamp: event.timestamp,
          isKeyEvent,
          keyEventMarker,
        });
        currentQueueParentId = event.parent_sequence_id;
        break;
      case 'QueueProgression':
        if (currentQueueParentId === null || event.parent_sequence_id === currentQueueParentId) {
            currentQueueProgressionEvents.push(event);
            currentQueueParentId = event.parent_sequence_id;
        } else {
            flushQueueProgression();
            currentQueueProgressionEvents.push(event);
            currentQueueParentId = event.parent_sequence_id;
        }
        break;
      case 'PartialFill':
        isKeyEvent = true;
        keyEventMarker = '⭐ Partial Fill';
        if (!firstExecutionEventAdded) {
            keyEventMarker = '⭐ Execution begins (Partial Fill)';
            firstExecutionEventAdded = true;
        }
        narrativeBlocks.push({
          group: 'Execution',
          narrative: `Execution started: Order ${getOrderId(event)} partially filled ${event.filled_qty} at price ${event.price}.`,
          id: event.sequence_id,
          parentId: event.parent_sequence_id,
          timestamp: event.timestamp,
          isKeyEvent,
          keyEventMarker,
        });
        break;
      case 'OrderFilled':
        if (!firstExecutionEventAdded) {
            isKeyEvent = true;
            keyEventMarker = '⭐ Execution begins (Full Fill)';
            firstExecutionEventAdded = true;
        }
        narrativeBlocks.push({
          group: 'Execution',
          narrative: `Order ${getOrderId(event)} fully executed.`,
          id: event.sequence_id,
          parentId: event.parent_sequence_id,
          timestamp: event.timestamp,
          isKeyEvent,
          keyEventMarker,
        });
        break;
      case 'MarketEvent':
        break;
      default:
        narrativeBlocks.push({
          group: 'Other',
          narrative: `Unhandled event type: ${event.type} for order ${eventOrderId}.`,
          id: event.sequence_id,
          parentId: event.parent_sequence_id,
          timestamp: event.timestamp,
          isKeyEvent,
          keyEventMarker,
        });
        break;
    }
  });

  flushQueueProgression();

  return narrativeBlocks;
};

// Helper to compare execution traces and identify divergences
const compareExecutionTraces = (trace1, trace2) => {
  const divergences = [];

  const len1 = trace1.length;
  const len2 = trace2.length;
  const maxLength = Math.max(len1, len2);

  if (len1 !== len2) {
    divergences.push(`Different number of narrative blocks: Strategy 1 (${len1}) vs Strategy 2 (${len2}).`);
  }

  for (let i = 0; i < maxLength; i++) {
    const block1 = trace1[i];
    const block2 = trace2[i];

    if (!block1 && block2) {
      divergences.push(`Strategy 1 ended earlier. Strategy 2 has block '${block2.group}' (Seq ${block2.id}) at step ${i + 1}.`);
      continue;
    }
    if (block1 && !block2) {
      divergences.push(`Strategy 2 ended earlier. Strategy 1 has block '${block1.group}' (Seq ${block1.id}) at step ${i + 1}.`);
      continue;
    }

    if (block1.group !== block2.group) {
      divergences.push(`Divergence in event group at step ${i + 1}: Strategy 1 has '${block1.group}' (Seq ${block1.id}) vs Strategy 2 has '${block2.group}' (Seq ${block2.id}).`);
    }
    if (block1.narrative !== block2.narrative) {
      divergences.push(`Divergence in narrative at step ${i + 1} for group '${block1.group}': Strategy 1 says '${block1.narrative}' vs Strategy 2 says '${block2.narrative}'.`);
    }

    // Check for presence of QueueProgression/PartialFill if applicable
    const hasQueueProgression1 = trace1.some(b => b.group === 'Queue Progression');
    const hasQueueProgression2 = trace2.some(b => b.group === 'Queue Progression');
    if (i === 0 && hasQueueProgression1 !== hasQueueProgression2) {
        divergences.push(`Divergence in queue progression: Strategy 1 ${hasQueueProgression1 ? 'had' : 'did not have'} queue progression vs Strategy 2 ${hasQueueProgression2 ? 'had' : 'did not have'} queue progression.`);
    }

    const hasPartialFill1 = trace1.some(b => b.group === 'Execution' && b.narrative.includes('partially filled'));
    const hasPartialFill2 = trace2.some(b => b.group === 'Execution' && b.narrative.includes('partially filled'));
    if (i === 0 && hasPartialFill1 !== hasPartialFill2) {
        divergences.push(`Divergence in partial fills: Strategy 1 ${hasPartialFill1 ? 'had' : 'did not have'} partial fills vs Strategy 2 ${hasPartialFill2 ? 'had' : 'did not have'} partial fills.`);
    }

  }

  return divergences.length > 0 ? divergences : ['No significant execution differences detected.'];
};


const StrategyInspector = ({ strategyId: propStrategyId, seed: propSeed, strategyId2: propStrategyId2, seed2: propSeed2, onReset }) => { // MODIFIED: Added strategyId2, seed2 props
  const [strategyId, setStrategyId] = useState(propStrategyId || '');
  const [seed, setSeed] = useState(propSeed || 42);
  const [inspectionResult, setInspectionResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // START: DUAL STRATEGY MODE - Local state for second strategy
  const [strategyId2, setStrategyId2] = useState(propStrategyId2 || '');
  const [seed2, setSeed2] = useState(propSeed2 || 42);
  const [inspectionResult2, setInspectionResult2] = useState(null);
  const [loading2, setLoading2] = useState(false);
  const [error2, setError2] = useState(null);
  // END: DUAL STRATEGY MODE

  const [selectedSeqId, setSelectedSeqId] = useState(null);
  const [selectedMaxSeqId, setSelectedMaxSeqId] = useState(null);
  const [showRawEvents, setShowRawEvents] = useState(false);

  const rawEventRefs = useRef({});

  // Update local state when props change (for primary strategy)
  useEffect(() => {
    setStrategyId(propStrategyId || '');
    setSeed(propSeed || 42);
  }, [propStrategyId, propSeed]);

  // Update local state when props change (for second strategy)
  useEffect(() => {
    setStrategyId2(propStrategyId2 || '');
    setSeed2(propSeed2 || 42);
  }, [propStrategyId2, propSeed2]);

  // Fetch data for primary strategy when its inputs change
  useEffect(() => {
    if (strategyId && seed !== null) {
      handleInspectStrategy(1);
    } else {
      setInspectionResult(null);
      setError(null);
    }
  }, [strategyId, seed]);

  // Fetch data for second strategy when its inputs change
  useEffect(() => {
    if (strategyId2 && seed2 !== null) {
      handleInspectStrategy(2);
    } else {
      setInspectionResult2(null);
      setError2(null);
    }
  }, [strategyId2, seed2]);

  // Sync raw event scroll on selection change
  useEffect(() => {
    if (selectedSeqId && showRawEvents && rawEventRefs.current[selectedSeqId]) {
      rawEventRefs.current[selectedSeqId].scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
      });
    }
  }, [selectedSeqId, showRawEvents]);

  // Modified handleInspectStrategy to accept a flag for which strategy to inspect
  const handleInspectStrategy = async (strategyNum) => {
    const isFirstStrategy = strategyNum === 1;
    const currentStrategyId = isFirstStrategy ? strategyId : strategyId2;
    const currentSeed = isFirstStrategy ? seed : seed2;

    if (!currentStrategyId || currentSeed === null) return;

    isFirstStrategy ? setLoading(true) : setLoading2(true);
    isFirstStrategy ? setError(null) : setError2(null);
    // isFirstStrategy ? setInspectionResult(null) : setInspectionResult2(null); // Keep previous result until new one loads
    setSelectedSeqId(null); // Reset selection on new inspection

    try {
      const response = await fetch('http://localhost:8000/inspect_strategy', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          strategy_id: currentStrategyId,
          seed: Number(currentSeed),
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to inspect strategy');
      }

      const data = await response.json();
      if (isFirstStrategy) {
        setInspectionResult(data);
        // Set initial maxSeqId to the highest sequence_id in the trace for primary strategy
        if (data.execution_trace && data.execution_trace.length > 0) {
          const maxId = Math.max(...data.execution_trace.map(e => e.sequence_id));
          setSelectedMaxSeqId(maxId);
        }
      } else {
        setInspectionResult2(data);
      }
    } catch (err) {
      isFirstStrategy ? setError(err.message) : setError2(err.message);
    } finally {
      isFirstStrategy ? setLoading(false) : setLoading2(false);
    }
  };

  const totalExecutionSteps = inspectionResult?.execution_trace?.length || 0;
  const partialFillsCount = inspectionResult?.execution_trace?.filter(
    (trace) => trace.type === 'PartialFill'
  ).length || 0;

  const totalExecutionSteps2 = inspectionResult2?.execution_trace?.length || 0;
  const partialFillsCount2 = inspectionResult2?.execution_trace?.filter(
    (trace) => trace.type === 'PartialFill'
  ).length || 0;

  const eventMap = {};
  // MODIFIED: Use all unique sequence IDs across both traces for the eventMap
  const allNarrativeBlocks1 = inspectionResult ? groupAndNarrateEvents(inspectionResult.execution_trace, null) : [];
  const allNarrativeBlocks2 = inspectionResult2 ? groupAndNarrateEvents(inspectionResult2.execution_trace, null) : [];

  [...allNarrativeBlocks1, ...allNarrativeBlocks2].forEach(block => {
    eventMap[block.id] = block;
  });

  const getCausalChain = (seqId) => {
    const chain = new Set();
    let current = seqId;

    while (current !== null && eventMap[current]) {
      chain.add(current);
      current = eventMap[current].parentId;
    }

    return chain;
  };

  const activeChain = selectedSeqId
    ? getCausalChain(selectedSeqId)
    : new Set();

  const narratedExecutionTrace1 = inspectionResult
    ? groupAndNarrateEvents(inspectionResult.execution_trace, selectedMaxSeqId)
    : [];
  const narratedExecutionTrace2 = inspectionResult2
    ? groupAndNarrateEvents(inspectionResult2.execution_trace, selectedMaxSeqId)
    : [];

  const minSeqId = inspectionResult && inspectionResult.execution_trace.length > 0
    ? Math.min(...inspectionResult.execution_trace.map(e => e.sequence_id))
    : 0;
  const maxAvailableSeqId = inspectionResult && inspectionResult.execution_trace.length > 0
    ? Math.max(...inspectionResult.execution_trace.map(e => e.sequence_id))
    : 0;

  // Helper for text color based on group
  const getGroupColorClass = (group) => {
    switch (group) {
      case 'Intent': return 'border-green-500 text-green-800 bg-green-50';
      case 'Queue Entry': return 'border-yellow-500 text-yellow-800 bg-yellow-50';
      case 'Queue Progression': return 'border-orange-500 text-orange-800 bg-orange-50';
      case 'Execution': return 'border-blue-500 text-blue-800 bg-blue-50';
      default: return 'border-gray-500 text-gray-800 bg-gray-50';
    }
  };

  // START: DUAL STRATEGY MODE - Determine if we are in comparison mode
  const isDualMode = (inspectionResult && inspectionResult2);

  // START: ADD: Timeline Context Banner
  const currentMaxSeqId = selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId;
  const timelineBanner = `Replay Position: Seq ${currentMaxSeqId} / ${maxAvailableSeqId}`;
  // END: ADD: Timeline Context Banner


  return (
    <div className="p-4">
      <h2 className="text-2xl font-semibold mb-4">Strategy Inspector</h2>

      <div className="mb-4 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="strategy_id">
            Strategy ID 1:
          </label>
          <input
            type="text"
            id="strategy_id"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={strategyId}
            onChange={(e) => setStrategyId(e.target.value)}
            onBlur={() => handleInspectStrategy(1)}
          />
        </div>

        {/* START: DUAL STRATEGY MODE - Second strategy input */}
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="strategy_id_2">
            Strategy ID 2 (Optional):
          </label>
          <input
            type="text"
            id="strategy_id_2"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={strategyId2}
            onChange={(e) => setStrategyId2(e.target.value)}
            onBlur={() => handleInspectStrategy(2)}
          />
        </div>
        {/* END: DUAL STRATEGY MODE */}
      </div>

      <div className="mb-6 grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="seed_inspect">
            Seed 1:
          </label>
          <input
            type="number"
            id="seed_inspect"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={seed}
            onChange={(e) => setSeed(e.target.value)}
            onBlur={() => handleInspectStrategy(1)}
          />
        </div>
        {/* START: DUAL STRATEGY MODE - Second seed input */}
        <div>
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="seed_inspect_2">
            Seed 2 (Optional):
          </label>
          <input
            type="number"
            id="seed_inspect_2"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            value={seed2}
            onChange={(e) => setSeed2(e.target.value)}
            onBlur={() => handleInspectStrategy(2)}
          />
        </div>
        {/* END: DUAL STRATEGY MODE */}
      </div>

      <button
        className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline mb-4"
        onClick={() => { handleInspectStrategy(1); if (strategyId2) handleInspectStrategy(2); }} // Trigger both if second ID is present
        disabled={loading || loading2}
      >
        {(loading || loading2) ? 'Inspecting...' : (isDualMode ? 'Compare Executions' : 'Inspect Strategy')}
      </button>

      {error && <p className="text-red-500 mt-4">Error (Strategy 1): {error}</p>}
      {error2 && <p className="text-red-500 mt-2">Error (Strategy 2): {error2}</p>}

      {inspectionResult && (
        <div className="mt-6 space-y-6">

          {/* START: ADD: System View Hint (Mental Model) */}
          <div className="border p-4 rounded-lg shadow-sm bg-gray-50">
            <h3 className="text-xl font-semibold mb-2">Execution Model</h3>
            <p className="text-sm text-gray-800">
              Decision → Queue → Market Interaction → Execution
            </p>
          </div>
          {/* END: ADD: System View Hint (Mental Model) */}

          {/* START: ADD: Timeline Context Banner */}
          <div className="p-3 bg-blue-100 rounded-lg text-blue-800 font-medium text-center shadow-sm">
            {timelineBanner}
          </div>
          {/* END: ADD: Timeline Context Banner */}

          {/* START: DUAL STRATEGY MODE - Conditional rendering for single vs dual view */}
          <div className={isDualMode ? "grid grid-cols-1 md:grid-cols-2 gap-6" : ""}>
            {/* Strategy 1 Column */}
            <div>
              {isDualMode && <h3 className="text-xl font-bold text-gray-800 mb-4">Strategy 1 ({strategyId})</h3>}
              {/* Section 1: Decision Context */}
              <div className="border p-4 rounded-lg shadow-sm mb-6">
                <h3 className="text-xl font-semibold mb-2">Decision Context</h3>
                <p><span className="font-medium">Strategy ID:</span> {inspectionResult.strategy_id}</p>
                <p><span className="font-medium">Seed:</span> {seed}</p>
                <div className="mt-2">
                  <p className="font-medium">Metrics:</p>
                  <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult.metrics, null, 2)}</pre>
                </div>
              </div>

              {/* Section 2: Execution Layer */}
              <div className="border p-4 rounded-lg shadow-sm mb-6">
                <h3 className="text-xl font-semibold mb-2">Execution Narrative</h3>

                {selectedSeqId && (
                  <button
                    className="text-sm text-gray-500 hover:text-gray-700 mb-2 underline"
                    onClick={() => setSelectedSeqId(null)}
                  >
                    Clear Causal Chain Selection
                  </button>
                )}

                <div className="mb-4 flex items-center space-x-2">
                  <label htmlFor="max-seq-id" className="text-sm text-gray-700">Replay Position (Seq ID):</label>
                  <input
                    type="range"
                    id="max-seq-id"
                    min={minSeqId}
                    max={maxAvailableSeqId}
                    value={selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                    onChange={(e) => setSelectedMaxSeqId(Number(e.target.value))}
                    className="w-full h-2 bg-blue-200 rounded-lg appearance-none cursor-pointer"
                  />
                  <span className="text-sm font-medium text-gray-800">
                    {selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                  </span>
                </div>
                <p className="text-sm text-gray-600 mb-4">
                  Showing events from Seq {minSeqId} → Seq {selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                </p>

                <div className="mb-4">
                  <label className="inline-flex items-center">
                    <input
                      type="checkbox"
                      className="form-checkbox text-blue-600"
                      checked={showRawEvents}
                      onChange={(e) => setShowRawEvents(e.target.checked)}
                    />
                    <span className="ml-2 text-gray-700">Show Raw Events (Debug Mode)</span>
                  </label>
                </div>

                <div className="bg-gray-50 p-4 rounded-md max-h-60 overflow-y-auto space-y-4">
                  {narratedExecutionTrace1.length > 0 ? (
                    narratedExecutionTrace1.map((block, blockIndex) => (
                      <React.Fragment key={block.id || blockIndex}>
                        <div
                          className={`
                            border-l-2 pl-3 pt-1 pb-1 cursor-pointer
                            ${activeChain.has(block.id)
                              ? `${getGroupColorClass(block.group)} border-l-4 border-blue-600 shadow-md`
                              : `border-gray-300 ${getGroupColorClass(block.group)} ${selectedSeqId ? 'opacity-50' : ''}`} /* Dim non-relevant blocks */
                            hover:bg-gray-200
                            transition-all duration-200
                          `}
                          onClick={() => setSelectedSeqId(block.id)}
                        >
                          {block.isKeyEvent && ( // KEY EVENT MARKER
                            <span className="text-purple-600 font-bold mr-2">{block.keyEventMarker}</span>
                          )}
                          <p className={`font-semibold mb-1 ${activeChain.has(block.id) ? 'text-blue-800' : getGroupColorClass(block.group).split(' ')[1]}`}>{block.group} (Seq: {block.id})</p>
                          <p className="text-sm text-gray-800">{block.narrative}</p>
                          {block.parentId !== undefined && block.parentId !== null && (
                            <p className={`text-xs text-gray-500 mt-1 ${activeChain.has(block.id) ? 'font-medium' : ''}`}>
                              Derived from Seq {block.parentId}
                            </p>
                          )}
                        </div>
                        {blockIndex < narratedExecutionTrace1.length - 1 && (
                          <div className="text-gray-400 text-sm ml-2">↓</div>
                        )}
                      </React.Fragment>
                    ))
                  ) : (
                    <p>No execution narrative available for Strategy 1.</p>
                  )}
                </div>

                {selectedSeqId && inspectionResult && (
                  <div className="mt-6 border p-4 rounded-lg shadow-sm bg-gray-50">
                    <h3 className="text-xl font-semibold mb-3">Causal Chain for Seq {selectedSeqId}</h3>
                    <button
                      className="text-sm text-gray-500 hover:text-gray-700 mb-2 underline"
                      onClick={() => setSelectedSeqId(null)}
                    >
                      Clear Causal Chain Selection
                    </button>
                    <div className="space-y-2 mt-2">
                      {Array.from(activeChain)
                        .sort((a, b) => b - a)
                        .map((seqIdInChain, idx) => {
                          const block = eventMap[seqIdInChain];
                          if (!block) return null;

                          return (
                            <div key={block.id} className={`border-l-2 pl-3 ${getGroupColorClass(block.group)} pt-1 pb-1`}>
                              <p className={`font-semibold text-blue-700 mb-1`}>{block.group} (Seq: {block.id})</p>
                              <p className="text-sm text-gray-800">{block.narrative}</p>
                              {idx < activeChain.size - 1 && (
                                <div className="text-gray-400 text-sm ml-2 mt-1">↑</div>
                              )}
                            </div>
                          );
                        })}
                    </div>
                  </div>
                )}

                {showRawEvents && inspectionResult.execution_trace.length > 0 && (
                  <div className="mt-4 p-4 bg-gray-700 text-white rounded-md">
                    <h4 className="text-lg font-semibold mb-2">Raw Execution Trace JSON (Strategy 1)</h4>
                    <div className="text-sm overflow-x-auto space-y-2">
                      {inspectionResult.execution_trace.map((event, index) => (
                        <pre
                          key={event.sequence_id || index}
                          ref={el => rawEventRefs.current[event.sequence_id] = el}
                          className={`
                            p-2 rounded-md transition-colors duration-200
                            ${activeChain.has(event.sequence_id) ? 'bg-blue-600 text-white' : 'bg-gray-600 text-gray-100'}
                          `}
                        >
                          {JSON.stringify(event, null, 2)}
                        </pre>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Section 3: Outcome Layer */}
              <div className="border p-4 rounded-lg shadow-sm">
                <h3 className="text-xl font-semibold mb-2">Outcome Layer</h3>
                <p><span className="font-medium">Final Metrics:</span></p>
                <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult.metrics, null, 2)}</pre>
                <p className="mt-2"><span className="font-medium">Total Execution Steps:</span> {totalExecutionSteps}</p>
                <p><span className="font-medium">Count of Partial Fills:</span> {partialFillsCount}</p>
              </div>
            </div>

            {/* START: DUAL STRATEGY MODE - Strategy 2 Column */}
            {isDualMode && inspectionResult2 && (
              <div>
                <h3 className="text-xl font-bold text-gray-800 mb-4">Strategy 2 ({strategyId2})</h3>
                 {/* Section 1: Decision Context */}
                <div className="border p-4 rounded-lg shadow-sm mb-6">
                  <h3 className="text-xl font-semibold mb-2">Decision Context</h3>
                  <p><span className="font-medium">Strategy ID:</span> {inspectionResult2.strategy_id}</p>
                  <p><span className="font-medium">Seed:</span> {seed2}</p>
                  <div className="mt-2">
                    <p className="font-medium">Metrics:</p>
                    <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult2.metrics, null, 2)}</pre>
                  </div>
                </div>

                {/* Section 2: Execution Layer */}
                <div className="border p-4 rounded-lg shadow-sm mb-6">
                  <h3 className="text-xl font-semibold mb-2">Execution Narrative</h3>

                  {selectedSeqId && (
                    <button
                      className="text-sm text-gray-500 hover:text-gray-700 mb-2 underline"
                      onClick={() => setSelectedSeqId(null)}
                    >
                      Clear Causal Chain Selection
                    </button>
                  )}

                  <div className="mb-4 flex items-center space-x-2">
                    <label htmlFor="max-seq-id-2" className="text-sm text-gray-700">Replay Position (Seq ID):</label>
                    <input
                      type="range"
                      id="max-seq-id-2"
                      min={minSeqId}
                      max={maxAvailableSeqId}
                      value={selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                      onChange={(e) => setSelectedMaxSeqId(Number(e.target.value))}
                      className="w-full h-2 bg-blue-200 rounded-lg appearance-none cursor-pointer"
                    />
                    <span className="text-sm font-medium text-gray-800">
                      {selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                    </span>
                  </div>
                  <p className="text-sm text-gray-600 mb-4">
                    Showing events from Seq {minSeqId} → Seq {selectedMaxSeqId !== null ? selectedMaxSeqId : maxAvailableSeqId}
                  </p>

                  <div className="mb-4">
                    <label className="inline-flex items-center">
                      <input
                        type="checkbox"
                        className="form-checkbox text-blue-600"
                        checked={showRawEvents}
                        onChange={(e) => setShowRawEvents(e.target.checked)}
                      />
                      <span className="ml-2 text-gray-700">Show Raw Events (Debug Mode)</span>
                    </label>
                  </div>

                  <div className="bg-gray-50 p-4 rounded-md max-h-60 overflow-y-auto space-y-4">
                    {narratedExecutionTrace2.length > 0 ? (
                      narratedExecutionTrace2.map((block, blockIndex) => (
                        <React.Fragment key={block.id || blockIndex}>
                          <div
                            className={`
                              border-l-2 pl-3 pt-1 pb-1 cursor-pointer
                              ${activeChain.has(block.id)
                                ? `${getGroupColorClass(block.group)} border-l-4 border-blue-600 shadow-md`
                                : `border-gray-300 ${getGroupColorClass(block.group)} ${selectedSeqId ? 'opacity-50' : ''}`}
                              hover:bg-gray-200
                              transition-all duration-200
                            `}
                            onClick={() => setSelectedSeqId(block.id)}
                          >
                            {block.isKeyEvent && (
                              <span className="text-purple-600 font-bold mr-2">{block.keyEventMarker}</span>
                            )}
                            <p className={`font-semibold mb-1 ${activeChain.has(block.id) ? 'text-blue-800' : getGroupColorClass(block.group).split(' ')[1]}`}>{block.group} (Seq: {block.id})</p>
                            <p className="text-sm text-gray-800">{block.narrative}</p>
                            {block.parentId !== undefined && block.parentId !== null && (
                              <p className={`text-xs text-gray-500 mt-1 ${activeChain.has(block.id) ? 'font-medium' : ''}`}>
                                Derived from Seq {block.parentId}
                              </p>
                            )}
                          </div>
                          {blockIndex < narratedExecutionTrace2.length - 1 && (
                            <div className="text-gray-400 text-sm ml-2">↓</div>
                          )}
                        </React.Fragment>
                      ))
                    ) : (
                      <p>No execution narrative available for Strategy 2.</p>
                    )}
                  </div>

                  {selectedSeqId && inspectionResult2 && (
                    <div className="mt-6 border p-4 rounded-lg shadow-sm bg-gray-50">
                      <h3 className="text-xl font-semibold mb-3">Causal Chain for Seq {selectedSeqId}</h3>
                      <button
                        className="text-sm text-gray-500 hover:text-gray-700 mb-2 underline"
                        onClick={() => setSelectedSeqId(null)}
                      >
                        Clear Causal Chain Selection
                      </button>
                      <div className="space-y-2 mt-2">
                        {Array.from(activeChain)
                          .sort((a, b) => b - a)
                          .map((seqIdInChain, idx) => {
                            const block = eventMap[seqIdInChain];
                            if (!block) return null;

                            return (
                              <div key={block.id} className={`border-l-2 pl-3 ${getGroupColorClass(block.group)} pt-1 pb-1`}>
                                <p className={`font-semibold text-blue-700 mb-1`}>{block.group} (Seq: {block.id})</p>
                                <p className="text-sm text-gray-800">{block.narrative}</p>
                                {idx < activeChain.size - 1 && (
                                  <div className="text-gray-400 text-sm ml-2 mt-1">↑</div>
                                )}
                              </div>
                            );
                          })}
                      </div>
                    </div>
                  )}

                  {showRawEvents && inspectionResult2.execution_trace.length > 0 && (
                    <div className="mt-4 p-4 bg-gray-700 text-white rounded-md">
                      <h4 className="text-lg font-semibold mb-2">Raw Execution Trace JSON (Strategy 2)</h4>
                      <div className="text-sm overflow-x-auto space-y-2">
                        {inspectionResult2.execution_trace.map((event, index) => (
                          <pre
                            key={event.sequence_id || index}
                            ref={el => rawEventRefs.current[event.sequence_id] = el}
                            className={`
                              p-2 rounded-md transition-colors duration-200
                              ${activeChain.has(event.sequence_id) ? 'bg-blue-600 text-white' : 'bg-gray-600 text-gray-100'}
                            `}
                          >
                            {JSON.stringify(event, null, 2)}
                          </pre>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Section 3: Outcome Layer */}
                <div className="border p-4 rounded-lg shadow-sm">
                  <h3 className="text-xl font-semibold mb-2">Outcome Layer</h3>
                  <p><span className="font-medium">Final Metrics:</span></p>
                  <pre className="bg-gray-50 p-2 rounded-md text-sm text-gray-800">{JSON.stringify(inspectionResult2.metrics, null, 2)}</pre>
                  <p className="mt-2"><span className="font-medium">Total Execution Steps:</span> {totalExecutionSteps2}</p>
                  <p><span className="font-medium">Count of Partial Fills:</span> {partialFillsCount2}</p>
                </div>
              </div>
            )}
            {/* END: DUAL STRATEGY MODE - Strategy 2 Column */}
          </div>
          {/* END: DUAL STRATEGY MODE - Conditional rendering */}

          {/* START: ADD: Divergence Detection */}
          {isDualMode && (narratedExecutionTrace1.length > 0 || narratedExecutionTrace2.length > 0) && (
            <div className="mt-6 border p-4 rounded-lg shadow-sm bg-red-50">
              <h3 className="text-xl font-semibold mb-2 text-red-800">Execution Divergence Analysis</h3>
              <ul className="list-disc list-inside text-sm text-red-700">
                {compareExecutionTraces(allNarrativeBlocks1, allNarrativeBlocks2).map((diff, index) => (
                  <li key={index}>{diff}</li>
                ))}
              </ul>
            </div>
          )}
          {/* END: ADD: Divergence Detection */}
        </div>
      )}
    </div>
  );
};

export default StrategyInspector;
